const API='/api';let token=localStorage.getItem('disha_token'),user=JSON.parse(localStorage.getItem('disha_user')||'null'),active='overview';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
async function api(url,opt={}){const isForm=opt.body instanceof FormData;const headers={...(isForm?{}:{'Content-Type':'application/json'}),...(token?{Authorization:'Bearer '+token}:{})};const r=await fetch(API+url,{...opt,headers:{...headers,...(opt.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||'Request failed');return d}
const asArray=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:Array.isArray(v?.rows)?v.rows:Array.isArray(v?.items)?v.items:[];
const roleLabel=r=>({admin:'Government Authority',trainee:'Trainee Portal',provider:'Training Provider',employer:'Employer Workspace'}[r]||r);
function landingView(){$('#app').innerHTML=`<div class="landing"><header class="landing-nav"><div class="brand dark">DI<span>SHA</span></div><span>Maharashtra Skilling Outcomes & Impact Platform</span><button class="mini-btn" id="landingLogin">Sign In</button></header><section class="landing-hero"><div class="landing-copy"><div class="gov-label">GOVERNMENT SKILLING & OUTCOME TRACKING</div><h1>Learn. Get skilled.<br><span>Build your future.</span></h1><p>DISHA connects learners with government-supported training programmes and tracks the journey from enrolment and certification to employment and long-term livelihood outcomes.</p><div class="landing-actions"><button class="btn" id="exploreRole">Get Started</button><button class="btn secondary" id="learnMore">How DISHA Works</button></div></div><div class="landing-stat"><b>One connected journey</b><div>Explore courses → Enrol → Train → Get certified → Build a career</div><small>Consent-based · Privacy conscious · Outcome focused</small></div></section><section class="role-section"><div><div class="gov-label">CHOOSE YOUR PORTAL</div><h2>How would you like to continue?</h2><p>Select your role to access the right DISHA portal.</p></div><div class="role-grid"><button class="role-card" data-role="trainee"><span>👨‍🎓</span><b>Student / Trainee</b><small>Explore all government courses, enrol yourself, manage your profile and track certificates & career outcomes.</small><em>Login or Register →</em></button><button class="role-card" data-role="admin"><span>🏛️</span><b>Government / Admin</b><small>Monitor programmes, providers, outcomes, verification, skill gaps and policy intelligence.</small><em>Admin Login →</em></button><button class="role-card" data-role="provider"><span>🏫</span><b>Training Provider</b><small>Manage batches, trainees, attendance, assessments, certificates and training outcomes.</small><em>Provider Login →</em></button><button class="role-card" data-role="employer"><span>🏢</span><b>Employer / Company</b><small>Connect hiring requirements with skilled candidates and verify employment outcomes.</small><em>Employer Login →</em></button></div></section><section class="solve-section" id="solve"><h2>What problem does DISHA solve?</h2><div class="solve-grid"><div><b>Training is not the final outcome</b><p>Traditional systems often stop at enrolment, attendance and certification. DISHA follows what happens after training.</p></div><div><b>Missing employment evidence</b><p>It captures self-reported outcomes, employer verification and follow-ups while keeping verification status transparent.</p></div><div><b>Better skilling decisions</b><p>Government can compare providers, courses, districts, skill gaps, retention and wage progression for evidence-based action.</p></div></div></section><footer>© DISHA · Government Skilling & Outcome Intelligence Platform</footer></div>`;document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>authView(b.dataset.role));$('#landingLogin').onclick=()=>authView();$('#exploreRole').onclick=()=>document.querySelector('.role-section').scrollIntoView({behavior:'smooth'});$('#learnMore').onclick=()=>$('#solve').scrollIntoView({behavior:'smooth'})}
function authView(preferredRole=''){$('#app').innerHTML=`<div class="auth"><section class="hero"><div class="brand">DI<span>SHA</span></div><div class="eyebrow">MAHARASHTRA SKILLING OUTCOMES & IMPACT PLATFORM</div><h1>From training to long-term livelihood outcomes.</h1><p>Choose a role, sign in securely and access the workspace built for your part in the skilling ecosystem.</p><button class="btn secondary back-btn" id="backHome">← Back to DISHA Home</button></section><section class="auth-card"><div class="form-card"><div class="brand dark">DI<span>SHA</span></div><p class="sub">Maharashtra Government Skilling & Outcome Intelligence Portal</p><div class="role-select"><label>Continue as</label><select id="roleSelect"><option value="">Select your portal</option><option value="trainee">Student / Trainee</option><option value="admin">Government / Admin</option><option value="provider">Training Provider</option><option value="employer">Employer / Company</option></select></div><div class="tabs"><button class="active" id="loginTab">Login</button><button id="registerTab">Trainee Registration</button></div><div id="authForm"></div></div></section></div>`;$('#roleSelect').value=preferredRole;const sync=()=>{const trainee=$('#roleSelect').value==='trainee';$('#registerTab').style.display=trainee?'block':'none';if(!trainee)showLogin()};$('#roleSelect').onchange=sync;sync();showLogin();$('#loginTab').onclick=showLogin;$('#registerTab').onclick=showRegister;$('#backHome').onclick=landingView}
function showLogin(){$('#loginTab').classList.add('active');$('#registerTab').classList.remove('active');$('#authForm').innerHTML=`<h2>Welcome back</h2><p class="sub">Sign in to the DISHA workspace selected above.</p><form id="loginForm"><div class="field"><label>Email</label><input type="email" name="email" required placeholder="you@example.com"></div><div class="field"><label>Password</label><input type="password" name="password" required placeholder="Enter password"></div><button class="btn full">Login to DISHA</button></form><div class="demo"><b>Demo accounts (password: disha123)</b><br>Government: admin@disha.gov.in<br>Provider: provider@disha.gov.in<br>Employer: employer@disha.gov.in<br>Trainee: aman@example.com</div><div id="msg"></div>`;$('#loginForm').onsubmit=login}
function showRegister(){$('#registerTab').classList.add('active');$('#loginTab').classList.remove('active');$('#authForm').innerHTML=`<h2>Create trainee record</h2><p class="sub">Create your learner account first. After login, browse and self-enrol in available government skill courses.</p><form id="regForm"><div class="field"><label>Full name</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="form-grid"><div class="field"><label>Phone</label><input name="phone"></div><div class="field"><label>District</label><input name="district"></div></div><div class="form-grid"><div class="field"><label>Gender</label><select name="gender"><option>Prefer not to say</option><option>Male</option><option>Female</option><option>Other</option></select></div><div class="field"><label>Age group</label><select name="ageGroup"><option>18-24</option><option>25-34</option><option>35+</option></select></div></div><div class="field"><label>Education</label><input name="education" placeholder="10th / 12th / Graduate / Diploma"></div><div class="field"><label>Password</label><input name="password" type="password" minlength="6" required></div><label class="check"><input type="checkbox" name="consent"> I consent to privacy-conscious longitudinal outcome tracking and authorized follow-ups.</label><button class="btn full">Create Trainee Account</button></form><div id="msg"></div>`;$('#regForm').onsubmit=register}
function message(t,b=false){const e=$('#msg');if(e)e.innerHTML=`<div class="notice ${b?'error':''}">${esc(t)}</div>`}
async function login(e){e.preventDefault();try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});token=d.token;user=d.user;localStorage.setItem('disha_token',token);localStorage.setItem('disha_user',JSON.stringify(user));render()}catch(x){message(x.message,true)}}
async function register(e){e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.consent=!!e.target.consent.checked;try{await api('/auth/register',{method:'POST',body:JSON.stringify(o)});message('Registration successful. Please login with your new account.');showLogin()}catch(x){message(x.message,true)}}
const nav=[['overview','▦','Overview'],['courses','◈','Explore Courses'],['profile','☻','My Profile'],['outcome','✓','My Outcome & Verification'],['followupRequests','☎','Follow-up Requests'],['assignments','✓','Assessments & Assignments'],['dishaai','✦','DishaAI Career Coach'],['certificates','🎓','My Certificates'],['trainees','♙','Trainee Records'],['training','▣','Training Management'],['providers','♧','Training Providers'],['jobs','▤','Employment & Opportunities'],['verification','✓','Verification Center'],['followupEngine','☎','Follow-up Engine'],['analytics','▥','Outcome Analytics'],['skillgap','△','Skill Gap & Attrition'],['policy','✦','Policy Intelligence'],['datacenter','◫','Data Management']];
function allowed(id){const r=user.role;
 if(r==='admin')return ['overview','trainees','training','providers','jobs','verification','followupEngine','analytics','skillgap','policy','datacenter'].includes(id);
 if(r==='trainee')return ['overview','courses','profile','outcome','followupRequests','assignments','dishaai','certificates','training','jobs','verification','skillgap'].includes(id);
 if(r==='provider')return ['overview','trainees','training','followupEngine','analytics','skillgap'].includes(id);
 if(r==='employer')return ['overview','jobs','verification'].includes(id);
 return false;
}
function shell(){return `<div class="shell"><aside class="sidebar"><div class="side-brand"><div class="logo">DI</div><div><div class="brand">DISHA</div><small>OUTCOMES INTELLIGENCE</small></div></div><div class="nav-group">${user.role==='admin'?'GOVERNMENT WORKSPACE':user.role==='trainee'?'MY LEARNING SPACE':user.role==='provider'?'PROVIDER WORKSPACE':'EMPLOYER WORKSPACE'}</div>${nav.filter(x=>allowed(x[0])).map(x=>`<button class="nav-item ${active===x[0]?'active':''}" data-page="${x[0]}"><i>${x[1]}</i><span>${x[2]}</span></button>`).join('')}<div class="side-footer">DISHA Outcome Intelligence<br><small>Training → Evidence → Outcomes</small></div></aside><main class="main"><header class="topbar"><div><h2>${esc(nav.find(x=>x[0]===active)?.[2]||'DISHA')}</h2><p>${roleLabel(user.role)} · Maharashtra Skilling Outcomes & Impact Platform</p></div><div class="userbox"><div class="live">● LIVE</div><div class="avatar">${esc(user.name).slice(0,1)}</div><div class="usertext"><b>${esc(user.name)}</b><small>${roleLabel(user.role)}</small></div><button id="homeBtn" class="logout">Home</button><button id="logoutBtn" class="logout">Logout</button></div></header><section id="content" class="content"></section></main></div>`}
const title=(h,p,a='')=>`<div class="page-title"><div><div class="eyebrow darkey">LIVE OUTCOME DATA</div><h1>${h}</h1><p>${p}</p></div><div>${a}</div></div>`;
const badge=s=>{const c=s==='verified'||s==='completed'||s==='employed'||s==='self_employed'||s==='apprenticeship'?'good':s==='pending'||s==='job_search'||s==='certified'?'warn':s==='disputed'||s==='dropped_out'||s==='overdue'?'bad':'';return `<span class="badge ${c}">${esc(String(s||'not requested').replaceAll('_',' '))}</span>`};
function miniLine(data,labels=[],mode='count'){
 const max=Math.max(...data,1),w=560,h=220,left=46,bottom=28,top=18,right=16,plotW=w-left-right,plotH=h-top-bottom;
 const step=plotW/(data.length-1||1), pts=data.map((v,i)=>`${left+i*step},${top+plotH-(v/max)*plotH}`).join(' ');
 const ticks=[0,.25,.5,.75,1].map(x=>Math.round(max*x));
 const grids=ticks.map(v=>{const y=top+plotH-(v/max)*plotH;return `<g><line x1="${left}" y1="${y}" x2="${w-right}" y2="${y}" stroke="#e7edf4"/><text x="${left-8}" y="${y+4}" text-anchor="end" fill="#748398" font-size="10">${mode==='percent'?v+'%':v.toLocaleString()}</text></g>`}).join('');
 const points=data.map((v,i)=>{const x=left+i*step,y=top+plotH-(v/max)*plotH,label=labels[i]||`Stage ${i+1}`,value=mode==='percent'?v+'%':Number(v).toLocaleString();return `<g class="line-point tip-item" data-tip="${esc(label)}: ${value}"><title>${esc(label)}: ${value}</title><circle cx="${x}" cy="${y}" r="5" fill="#fff" stroke="#0f9d98" stroke-width="3"/><text x="${x}" y="${Math.max(12,y-11)}" text-anchor="middle" fill="#2f4158" font-size="10" font-weight="700">${value}</text></g>`}).join('');
 return `<svg class="chart-svg improved-line" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${grids}<polyline points="${pts}" fill="none" stroke="#0f9d98" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><path d="M ${pts.replaceAll(' ',', L ')} L ${w-right},${top+plotH} L ${left},${top+plotH} Z" fill="rgba(15,157,152,.10)"/>${points}</svg>`
}
function donut(values,labels,centerLabel='records'){
 const total=values.reduce((a,b)=>a+Number(b||0),0)||1;const colors=['#168d8b','#3568d4','#e39a20','#e15554','#718096','#8d6ad8','#4c9c68'];let at=0;
 const stops=values.map((raw,i)=>{const pct=Number(raw||0)/total*100;const a=at,b=at+pct;at=b;return `${colors[i%colors.length]} ${a.toFixed(2)}% ${b.toFixed(2)}%`}).join(', ');
 return `<div class="pro-donut-wrap"><div class="pro-donut conic-donut" style="background:conic-gradient(${stops})"><div class="pro-donut-center"><b>${total.toLocaleString()}</b><small>${esc(centerLabel)}</small></div></div><div class="legend pro-legend">${labels.map((x,i)=>{const v=Number(values[i]||0),pct=Math.round(v/total*100);return `<span class="tip-item" data-tip="${esc(x)}: ${v.toLocaleString()} (${pct}%)"><i style="background:${colors[i%colors.length]}"></i>${esc(x)} <b>${pct}%</b></span>`}).join('')}</div></div>`
}
function bars(obj,unit='records'){const rows=Object.entries(obj).filter(([k])=>k&&k!=='undefined').slice(0,7);const max=Math.max(...rows.map(([,v])=>v.total||v),1);return `<div class="bar-chart">${rows.map(([k,v])=>{const n=Number(v.total||v),o=Number(v.outcomes??v),pct=Math.max(7,Math.round(o/max*100));return `<div class="vbar tip-item" data-tip="${esc(k)}: ${o.toLocaleString()} ${unit}"><div class="vbar-fill" style="height:${pct}%"><span>${o}</span></div><small title="${esc(k)}">${esc(k).slice(0,12)}</small></div>`}).join('')}</div>`}
function interactiveDonut(values,labels,centerLabel='signals'){
 const total=values.reduce((a,b)=>a+Number(b||0),0)||1;const colors=['#168d8b','#3568d4','#e39a20','#e15554','#718096','#8d6ad8','#4c9c68'];let at=0;
 const stops=values.map((raw,i)=>{const pct=Number(raw||0)/total*100;const a=at,b=at+pct;at=b;return `${colors[i%colors.length]} ${a.toFixed(2)}% ${b.toFixed(2)}%`}).join(', ');
 return `<div class="interactive-donut-wrap pro-donut-layout"><div class="pro-donut conic-donut" style="background:conic-gradient(${stops})"><div class="pro-donut-center"><b>${total.toLocaleString()}</b><small>${esc(centerLabel)}</small></div></div><div class="interactive-legend">${labels.map((x,i)=>{const v=Number(values[i]||0),pct=Math.round(v/total*100);return `<span class="tip-item" data-tip="${esc(x)}: ${v.toLocaleString()} records (${pct}%)"><i style="background:${colors[i%colors.length]}"></i>${esc(x)} <b>${pct}%</b></span>`}).join('')}</div></div>`
}
function interactiveBars(obj,unit='records'){
 const rows=Object.entries(obj||{}).filter(([k])=>k&&k!=='undefined').slice(0,7);if(!rows.length)return '<div class="empty">No chart data available.</div>';
 const vals=rows.map(([,v])=>Number(v?.total??v?.outcomes??v??0));const max=Math.max(...vals,1);const colors=['#2d8f8d','#e18400','#2876a8','#f04444','#5c5cc0','#e18400','#2d8f8d'];
 return `<div class="interactive-bars">${rows.map(([k,v],i)=>{const n=Number(v?.total??v?.outcomes??v??0),pct=Math.max(8,Math.round(n/max*100));return `<div class="ibar"><div class="ibar-track"><div class="ibar-fill tip-item" data-tip="${esc(k)}: ${n.toLocaleString()} ${unit} (${pct}% of highest)" style="height:${pct}%;background:${colors[i%colors.length]}"><span>${n}</span></div></div><small>${esc(k).slice(0,12)}</small></div>`}).join('')}</div>`
}
function journeyData(j={}){const stages=[['Enrolled',j.enrolled||0,'Enrollment completed'],['Certified',j.certified||0,'Assessment and certificate stage'],['Positive outcome',j.placed||0,'Employment / self-employment / apprenticeship'],['Retained 6 mo',j.retained6||0,'Six-month outcome confirmed'],['Retained 12 mo',j.retained12||0,'Long-term retention confirmed']];const max=Math.max(...stages.map(x=>Number(x[1])||0),1);return `<div class="journey-flow">${stages.map((x,i)=>`<div class="journey-step ${i===0?'active':''}"><div class="journey-num">${i+1}</div><div class="journey-count">${Number(x[1]).toLocaleString()}</div><b>${x[0]}</b><small>${x[2]}</small><div class="journey-bar"><i style="width:${Math.max(8,Math.round((Number(x[1])/max)*100))}%"></i></div></div>`).join('<div class="journey-arrow">→</div>')}</div>`}
function rateBars(rows,labelKey='name',valueKey='placementRate',extraKey='total'){
 const list=Object.entries(rows||{}).map(([name,v])=>({name,...v})).filter(x=>x[extraKey]!==0).sort((a,b)=>Number(b[valueKey]||0)-Number(a[valueKey]||0));
 if(!list.length)return '<div class="empty">No recorded data for this selection.</div>';
 return `<div class="rank-bars">${list.map(x=>`<div class="rank-row"><div class="rank-top"><span>${esc(x[labelKey])}</span><b>${Number(x[valueKey]||0)}%</b></div><div class="rank-track"><i style="width:${Math.max(2,Math.min(100,Number(x[valueKey]||0)))}%"></i></div><small>${Number(x[extraKey]||0).toLocaleString()} records · ${Number(x.positive??x.outcomes??0).toLocaleString()} positive outcomes</small></div>`).join('')}</div>`;
}
function demandBars(rows){
 const list=Object.entries(rows||{}).map(([skill,v])=>({skill,...v})).sort((a,b)=>Number(b.jobs||0)-Number(a.jobs||0));
 if(!list.length)return '<div class="empty">No open employer demand has been recorded.</div>';
 return `<div class="demand-list">${list.slice(0,10).map(x=>{const max=Math.max(...list.map(y=>Number(y.jobs||0)),1);return `<div class="demand-row"><div class="rank-top"><span>${esc(x.skill)}</span><b>${x.jobs} job signals</b></div><div class="rank-track dual"><i style="width:${Math.max(3,Math.round(x.jobs/max*100))}%"></i></div><small>${x.gap||0} trainee gap signals · ${x.trained||0} training-supply signals</small></div>`}).join('')}</div>`;
}
function retentionCards(r){
 const keys=['month3','month6','month12','month24','month36','month60'];
 return `<div class="retention-grid">${keys.map(k=>{const x=r[k]||{};return `<div class="ret-card"><small>${esc(x.label||k)}</small><b>${Number(x.rate||0)}%</b><span>${Number(x.retained||0)}/${Number(x.eligible||0)} retained</span><div class="rank-track"><i style="width:${Math.max(2,Math.min(100,Number(x.rate||0)))}%"></i></div></div>`}).join('')}</div>`;
}
function outcomeMixChart(m){return donut([m.employed||0,m.selfEmployed||0,m.apprenticeship||0,m.internship||0,m.jobSearch||0,m.furtherEducation||0,m.droppedOut||0,m.training||0,m.certified||0],['Employed','Self-employed','Apprenticeship','Internship','Seeking job','Further education','Dropped out','In training','Certified / awaiting outcome'],'records')}
async function initMaharashtraMap(stats,scope){
 const el=document.getElementById('mahaMap'); if(!el||typeof L==='undefined')return;
 try{
  const map=L.map(el,{scrollWheelZoom:false,zoomControl:true}).setView([19.35,75.1],6.5);
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:10}).addTo(map);
  const aliases={'chhatrapati sambhajinagar':['chhatrapati sambhajinagar','aurangabad'],'ahilyanagar':['ahilyanagar','ahmednagar'],'dharashiv':['dharashiv','osmanabad']};
  const norm=x=>String(x||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
  const lookup={};Object.entries(stats||{}).forEach(([k,v])=>lookup[norm(k)]=v);
  const resolve=props=>{const vals=Object.values(props||{}).filter(v=>typeof v==='string');for(const val of vals){const n=norm(val);if(lookup[n])return val;for(const [canon,a] of Object.entries(aliases))if(a.includes(n)&&lookup[norm(canon)])return canon;}return null};
  const colour=p=>p>=75?'#178c88':p>=60?'#55aaa0':p>=45?'#e5a43a':'#e45756';
  const geo=await fetch('https://raw.githubusercontent.com/ishawakankar/India_Districts/master/Maharashtra/maharashtra.geojson').then(r=>r.json());
  L.geoJSON(geo,{style:f=>{const name=resolve(f.properties);const d=name?lookup[norm(name)]:null;return {color:'#fff',weight:1,fillColor:colour(Number(d?.placementRate||0)),fillOpacity:.76}},onEachFeature:(f,l)=>{const name=resolve(f.properties);const d=name?lookup[norm(name)]:null;const title=name||'Maharashtra district';l.bindTooltip(`<b>${esc(title)}</b><br>Placement: ${Number(d?.placementRate||0)}%<br>Trainees: ${Number(d?.total||0)}<br>Avg wage: ₹${Number(d?.avgWage||0).toLocaleString()}`,{sticky:true});l.on('click',()=>{const select=document.getElementById('adminDistrict');if(select&&name){const target=[...select.options].find(o=>norm(o.value)===norm(name));if(target){select.value=target.value;select.dispatchEvent(new Event('change'))}}})}}).addTo(map);
  if(scope&&scope.district!=='All Maharashtra')map.setZoom(7.3);
 }catch(e){el.innerHTML='<div class="map-fallback"><b>Geographical map unavailable offline.</b><span>District performance table remains available below.</span></div>'}
}
function districtPie(stats){
 const entries=Object.entries(stats||{}).filter(([k,v])=>k&&Number(v?.positive||0)>0).sort((a,b)=>Number(b[1].positive||0)-Number(a[1].positive||0));
 if(!entries.length)return '<div class="empty">No district outcome data available.</div>';
 const total=entries.reduce((a,[,v])=>a+Number(v.positive||0),0)||1;
 const colors=['#168d8b','#3568d4','#e39a20','#e15554','#718096','#8d6ad8','#4c9c68','#2d8f8d','#2876a8','#d65db1'];let at=0;
 const stops=entries.map(([,v],i)=>{const pct=Number(v.positive||0)/total*100,a=at,b=at+pct;at=b;return `${colors[i%colors.length]} ${a.toFixed(2)}% ${b.toFixed(2)}%`}).join(', ');
 return `<div class="district-pie-wrap"><div class="district-pie conic-donut" style="background:conic-gradient(${stops})"><div class="pro-donut-center"><b>${total.toLocaleString()}</b><small>positive outcomes</small></div></div><div class="district-pie-legend">${entries.map(([name,v],i)=>{const n=Number(v.positive||0),share=Math.round(n/total*100);return `<div class="district-pie-item tip-item" data-tip="${esc(name)}: ${n} positive outcomes · ${Number(v.placementRate||0)}% outcome rate · ${Number(v.total||0)} trainees"><i style="background:${colors[i%colors.length]}"></i><span>${esc(name)}</span><b>${n} · ${share}%</b></div>`}).join('')}</div></div>`;
}
function providerOutcomeBars(rows){
 const list=(rows||[]).filter(x=>Number(x.total||0)>0).sort((a,b)=>Number(b.positive||0)-Number(a.positive||0));
 if(!list.length)return '<div class="empty">No provider outcome data available.</div>';
 const max=Math.max(...list.map(x=>Number(x.positive||0)),1);
 return `<div class="rank-bars provider-outcome-bars">${list.map((x,i)=>`<div class="rank-row"><div class="rank-top"><span><em class="rank-no">${i+1}</em>${esc(x.name)}</span><b>${Number(x.positive||0).toLocaleString()} outcomes</b></div><div class="rank-track"><i style="width:${Math.max(2,Math.round(Number(x.positive||0)/max*100))}%"></i></div><small>${Number(x.placementRate||0)}% outcome rate · ${Number(x.verified||0)} verified · ${Number(x.total||0)} trainees</small></div>`).join('')}</div>`;
}
function verificationOverview(v,h){
 return `<div class="verification-summary"><div class="verification-stat verified"><b>${Number(v?.verified||0)}</b><span>Employer verified</span></div><div class="verification-stat pending"><b>${Number(v?.pending||0)}</b><span>Pending confirmation</span></div><div class="verification-stat disputed"><b>${Number(v?.disputed||0)}</b><span>Disputed</span></div><div class="verification-stat self"><b>${Number(v?.selfReported||0)}</b><span>Self-reported positive outcomes</span></div><div class="verification-stat pending"><b>${Number(v?.noResponse||0)}</b><span>Follow-up no response</span></div></div><div class="verification-hierarchy">${(h||[]).map(x=>`<div class="vh-step"><b>${x.level}</b><div><strong>${esc(x.label)}</strong><small>${esc(x.detail)}</small></div></div>`).join('')}</div><div class="notice"><b>Transparency rule:</b> self-reported outcomes are never presented as independently verified. No response remains <b>Follow-up Pending / Outcome Unknown</b>; it is not automatically marked unemployed.</div>`;
}
